// Dispatches |message| to the matching entry of |methods|, replying through
// |responder|. Returns false without replying when the message names no method
// in the table, so a partly migrated domain can fall back to its old routing.
//
// DevToolMessageDispatcher has already checked the envelope. The checks below
// keep a malformed message from a direct caller, such as a test, from reaching
// JsonCpp conversions that abort.
template <typename Handler, size_t N>
bool TryDispatchCDPMethod(const cdpc::Method<Handler> (&methods)[N],
                          Handler& handler,
                          const std::shared_ptr<CDPResponder>& responder,
                          const Json::Value& message) {
  if (!message.isObject()) return false;
  const Json::Value& name = message["method"];
  if (!name.isString()) return false;
  const Json::Value& id = message["id"];
  if (!id.isInt64()) {
    if (!cdpc::FindMethod(methods, name.asString())) return false;
    responder->SendError(CDPErrorCode::InvalidRequest,
                         "Message must have integer 'id' property");
    return true;
  }
  return cdpc::Dispatch(methods, handler, name.asString(), id.asInt64(),
                        message["params"], responder, {},
                        kCDPCResultValidation) ==
         cdpc::DispatchResult::kDispatched;
}

// Like TryDispatchCDPMethod, but replies MethodNotFound for methods outside the
// table. Use it once the table covers the whole domain.
template <typename Handler, size_t N>
void DispatchCDPMethod(const cdpc::Method<Handler> (&methods)[N],
                       Handler& handler,
                       const std::shared_ptr<CDPResponder>& responder,
                       const Json::Value& message) {
  if (TryDispatchCDPMethod(methods, handler, responder, message)) return;
  if (!message.isObject() || !message["method"].isString()) {
    responder->SendError(CDPErrorCode::InvalidRequest,
                         "Message must have string 'method' property");
    return;
  }
  responder->SendError(CDPErrorCode::MethodNotFound,
                       "'" + message["method"].asString() + "' wasn't found");
}

